const float PI = 3.141592;

//Pattern Degree
float _PatternAngle = 30.0;
//Tile Pattern Count
float _PatternCount = 16.0;
//Hologram Degree
float _HologramAngle = 15.0;

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord/iResolution.xy;

    //Aspect follow
    uv.y *= iResolution.y/iResolution.x;
    //Tile Pattern
    uv *= _PatternCount;

    //Pattern Rotation
    float angleRadian = radians(_PatternAngle);
    float angleCos = cos(angleRadian);
    float angleSin = sin(angleRadian);
    uv = mat2(angleCos, -angleSin, angleSin, angleCos) * uv;

    float hologramAngle = radians(_HologramAngle);

    //Hologram Animtion by Mouse Cursor 
    hologramAngle += radians(iMouse.x);

    //Hologram
    uv = fract(uv + 0.5) - 0.5;
    float value = (atan(uv.y,uv.x) + hologramAngle) / PI;
    value = abs( fract(value) * 2.0 - 1.0);

    fragColor = vec4(value,value,value,1.0);
}
